import * as THREE from "three";
import type { BodyId } from "../science/bodies";

/*
 * Procedural planets. Every surface is generated by a shader, so nothing is downloaded. These are
 * stylised models for the game (sizes and orbits are not to scale), inspired by what each world
 * really looks like. The map's info panel labels which values are measurements and which are
 * simplified.
 */

const NOISE = /* glsl */ `
  float hash3(vec3 p) { p = fract(p * 0.3183099 + 0.1); p *= 17.0; return fract(p.x * p.y * p.z * (p.x + p.y + p.z)); }
  float noise3(vec3 x) {
    vec3 i = floor(x), f = fract(x);
    f = f * f * (3.0 - 2.0 * f);
    return mix(
      mix(mix(hash3(i), hash3(i + vec3(1, 0, 0)), f.x), mix(hash3(i + vec3(0, 1, 0)), hash3(i + vec3(1, 1, 0)), f.x), f.y),
      mix(mix(hash3(i + vec3(0, 0, 1)), hash3(i + vec3(1, 0, 1)), f.x), mix(hash3(i + vec3(0, 1, 1)), hash3(i + vec3(1, 1, 1)), f.x), f.y),
      f.z);
  }
  float fbm3(vec3 p) { float v = 0.0, a = 0.5; for (int i = 0; i < 5; i++) { v += a * noise3(p); p *= 2.03; a *= 0.5; } return v; }
  float fbm3lo(vec3 p) { float v = 0.0, a = 0.5; for (int i = 0; i < 3; i++) { v += a * noise3(p); p *= 2.03; a *= 0.5; } return v; }

  // A cratered terrain layer: each cell may hold a bowl with a raised rim.
  float craterLayer(vec3 p, float scale, float minSize) {
    vec3 q = p * scale;
    vec3 i = floor(q);
    vec3 f = fract(q);
    float h = 0.0;
    for (int x = -1; x <= 1; x++) for (int y = -1; y <= 1; y++) for (int z = -1; z <= 1; z++) {
      vec3 g = vec3(float(x), float(y), float(z));
      vec3 id = i + g;
      float size = hash3(id + 3.7);
      if (size < minSize) continue;
      vec3 o = vec3(hash3(id), hash3(id + 7.1), hash3(id + 13.3));
      float d = length(g + o - f);
      float R = 0.12 + 0.32 * size;
      float t = d / R;
      h += -smoothstep(1.0, 0.0, t) * 0.55 + smoothstep(0.78, 1.0, t) * smoothstep(1.4, 1.0, t) * 0.32;
    }
    return h;
  }
  float craterTerrain(vec3 p) { return craterLayer(p, 5.0, 0.30) + craterLayer(p + 4.0, 12.0, 0.45) * 0.55 + craterLayer(p + 9.0, 26.0, 0.6) * 0.3; }
`;

const VERT = /* glsl */ `
  varying vec3 vObj;
  varying vec3 vWorldNormal;
  varying vec3 vWorldPos;
  void main() {
    vObj = normalize(position);
    vec4 world = modelMatrix * vec4(position, 1.0);
    vWorldPos = world.xyz;
    vWorldNormal = normalize(mat3(modelMatrix) * normal);
    gl_Position = projectionMatrix * viewMatrix * world;
  }
`;

const FRAG = /* glsl */ `
  precision highp float;
  varying vec3 vObj;
  varying vec3 vWorldNormal;
  varying vec3 vWorldPos;
  uniform int uType;
  uniform float uTime;
  uniform float uRadius;
  uniform vec3 uSun;
  uniform vec3 uColA;
  uniform vec3 uColB;
  uniform vec3 uColC;
  uniform float uBands;
  uniform vec3 uAtmo;
  uniform float uAtmoPower;
  uniform float uHighlight;
  ${NOISE}

  // Screen-space bump mapping: tilts the normal using the height field's slope across the screen.
  vec3 bump(vec3 n, float h, float strength) {
    vec3 dpx = dFdx(vWorldPos);
    vec3 dpy = dFdy(vWorldPos);
    float dhx = dFdx(h);
    float dhy = dFdy(h);
    vec3 r1 = cross(dpy, n);
    vec3 r2 = cross(n, dpx);
    float det = dot(dpx, r1);
    vec3 grad = sign(det) * (dhx * r1 + dhy * r2);
    // Fine relief turns to noise when a world covers only a few pixels, so fade it out with distance and cap the tilt.
    float fade = 1.0 - smoothstep(0.004, 0.02, length(dpx) / uRadius);
    vec3 d = strength * fade * uRadius * grad / max(abs(det), 1e-9);
    float m = length(d);
    d *= min(1.0, 0.7 / max(m, 1e-5));
    return normalize(n - d);
  }

  float cloudAt(vec3 p, float t) {
    vec3 q = p * 2.5 + vec3(t * 0.010, 0.0, t * 0.006);
    float w = fbm3(q * 1.7 + 4.0);
    return smoothstep(0.50, 0.80, fbm3(q + w * 0.95));
  }

  void main() {
    vec3 p = normalize(vObj);
    vec3 n = normalize(vWorldNormal);
    vec3 L = normalize(uSun);
    vec3 view = normalize(cameraPosition - vWorldPos);
    vec3 surface = vec3(0.0);
    float emissive = 0.0;
    float gloss = 0.0;
    float nightLights = 0.0;
    float aurora = 0.0;

    if (uType == 0) {
      // Rocky, airless world: cratered terrain with darker plains.
      float h = craterTerrain(p);
      float plains = smoothstep(0.50, 0.62, fbm3(p * 1.8 + 5.0));
      surface = mix(uColB, uColA, plains * 0.85);
      surface *= 0.82 + 0.34 * fbm3(p * 9.0) + h * 0.14;
      n = bump(n, h, 0.10);
    } else if (uType == 1) {
      // Earth: biomes, relief, ocean, clouds, city lights and aurora.
      float hgt = fbm3(p * 1.6 + 3.1) * 0.75 + fbm3(p * 3.4 + 9.0) * 0.25;
      float land = smoothstep(0.495, 0.512, hgt);
      float lat = abs(p.y);
      float elev = clamp((hgt - 0.51) * 3.2, 0.0, 1.0);
      float moist = fbm3(p * 2.6 + 17.0);
      float dry = smoothstep(0.12, 0.30, lat) * (1.0 - smoothstep(0.40, 0.58, lat)) * smoothstep(0.58, 0.40, moist);
      vec3 ground = mix(vec3(0.035, 0.12, 0.05), vec3(0.20, 0.27, 0.09), smoothstep(0.38, 0.70, moist));
      ground = mix(ground, vec3(0.30, 0.32, 0.27), smoothstep(0.55, 0.75, lat));
      ground = mix(ground, vec3(0.66, 0.52, 0.32), dry);
      ground = mix(ground, vec3(0.30, 0.26, 0.23), smoothstep(0.30, 0.75, elev));
      ground *= 0.78 + 0.44 * noise3(p * 70.0);
      float snowAmt = smoothstep(0.80, 0.90, lat + elev * 0.08 + (fbm3(p * 6.0) - 0.5) * 0.12);
      ground = mix(ground, vec3(0.93, 0.95, 1.0), snowAmt);
      float depth = smoothstep(0.512, 0.30, hgt);
      vec3 ocean = mix(vec3(0.03, 0.30, 0.42), vec3(0.004, 0.025, 0.11), pow(depth, 0.6));
      ocean = mix(ocean, vec3(0.93, 0.95, 1.0), smoothstep(0.84, 0.93, lat + (fbm3(p * 5.0) - 0.5) * 0.1));
      surface = mix(ocean, ground, land);
      float cl = cloudAt(p, uTime);
      n = bump(n, noise3(p * 60.0) * land * (0.25 + elev), 0.05);
      float diffE = dot(n, L);
      surface *= 1.0 - 0.4 * cloudAt(p - L * 0.02, uTime);
      surface = mix(surface, vec3(1.0, 0.99, 0.97), cl * 0.9);
      gloss = (1.0 - land) * (1.0 - cl);
      float pop = smoothstep(0.52, 0.74, fbm3(p * 9.0 + 2.0));
      float cityN = noise3(p * 34.0) * 0.6 + noise3(p * 70.0) * 0.4;
      nightLights = smoothstep(0.62, 0.80, cityN) * pop * land * (1.0 - smoothstep(0.75, 0.9, lat)) * (1.0 - cl * 0.8) * (0.75 + 0.25 * sin(uTime * 2.0 + p.x * 200.0));
      float ab = smoothstep(0.88, 0.92, lat) * (1.0 - smoothstep(0.95, 0.985, lat));
      aurora = ab * (0.5 + 0.5 * sin(atan(p.z, p.x) * 9.0 + uTime * 0.6 + fbm3(p * 4.0 + uTime * 0.05) * 6.0));
    } else if (uType == 2) {
      // Venus: featureless-looking sulphuric cloud deck, with streaks swept around by fast winds.
      float flow = fbm3(vec3(p.x * 2.0 + uTime * 0.012, p.y * 6.0, p.z * 2.0) + fbm3(p * 3.0 + uTime * 0.01) * 1.8);
      surface = mix(uColA, uColB, smoothstep(0.30, 0.78, flow));
      surface = mix(surface, uColA * 0.7, smoothstep(0.62, 0.8, fbm3(p * 5.0 + uTime * 0.02)) * 0.35);
    } else if (uType == 3) {
      // Mars: rust-coloured regolith, dark volcanic regions, ice caps and thin dust.
      float h = fbm3(p * 3.0 + 1.7);
      surface = mix(uColA, uColB, smoothstep(0.35, 0.65, h));
      surface = mix(surface, uColC, smoothstep(0.55, 0.7, fbm3(p * 8.0)) * 0.45);
      surface = mix(surface, uColC * 0.8, smoothstep(0.6, 0.72, fbm3(p * 2.0 + 7.0)) * 0.6);
      float cap = smoothstep(0.86, 0.93, abs(p.y) + (fbm3(p * 6.0) - 0.5) * 0.08);
      surface = mix(surface, vec3(0.93, 0.93, 0.95), cap);
      n = bump(n, h * 0.6 + craterTerrain(p) * 0.25, 0.08);
    } else if (uType == 4 || uType == 5) {
      // Gas and ice giants: bands sheared into eddies, and a large storm on Jupiter.
      float lat = p.y;
      float eddy = fbm3(vec3(p.x * 3.0 + lat * 6.0, lat * 2.0, p.z * 3.0) + uTime * 0.01) * 0.16;
      float warp = fbm3(vec3(p.x * 3.0, lat * 1.5, p.z * 3.0) + uTime * 0.01) * 0.12;
      float band = sin((lat + warp + eddy) * uBands) * 0.5 + 0.5;
      float fine = fbm3(vec3(p.x * 2.0 + eddy * 4.0, lat * uBands * 1.2, p.z * 2.0));
      surface = mix(uColA, uColB, band);
      surface = mix(surface, uColC, smoothstep(0.45, 0.8, fine) * (uType == 4 ? 0.55 : 0.2));
      if (uType == 4 && uBands > 20.0) {
        // Great Red Spot: a swirling oval with a brighter rim.
        vec3 spot = normalize(vec3(0.9, -0.3, 0.3));
        vec3 d3 = p - spot;
        float d = length(vec2(d3.x * 0.7, d3.y * 1.5 + d3.z * 0.3));
        float swirl = fbm3(p * 14.0 + vec3(0.0, atan(d3.y, d3.z) * 1.2 + uTime * 0.05, 0.0));
        surface = mix(surface, mix(vec3(0.72, 0.28, 0.18), vec3(0.9, 0.55, 0.4), swirl), smoothstep(0.28, 0.12, d) * 0.9);
        surface += vec3(0.25, 0.2, 0.15) * smoothstep(0.30, 0.26, d) * smoothstep(0.22, 0.26, d) * 0.5;
      }
      if (uType == 5 && uAtmoPower > 0.5 && uBands > 8.0) {
        // Neptune: a dark storm and bright methane cloud streaks.
        vec3 spot = normalize(vec3(-0.6, 0.3, 0.7));
        surface = mix(surface, uColC * 0.55, smoothstep(0.22, 0.08, length(p - spot)) * 0.7);
        surface += vec3(0.7, 0.8, 1.0) * smoothstep(0.7, 0.85, fbm3(vec3(p.x * 6.0, lat * 18.0, p.z * 6.0))) * 0.35;
      }
    } else {
      // The Sun: boiling granulation, cooler sunspots and a darkened, redder limb.
      float t = uTime * 0.05;
      float gran = fbm3(p * 5.0 + vec3(t, -t, t * 0.6)) + 0.5 * fbm3(p * 14.0 - vec3(t));
      surface = mix(uColA, uColB, smoothstep(0.35, 1.0, gran));
      float spots = smoothstep(0.62, 0.72, fbm3(p * 2.2 + vec3(1.3, 0.0, 0.0) + t * 0.2)) * smoothstep(0.75, 0.2, abs(p.y));
      surface = mix(surface, vec3(0.22, 0.05, 0.0), spots * 0.85);
      surface += vec3(1.0, 0.85, 0.5) * smoothstep(0.55, 0.62, fbm3(p * 2.2 + vec3(1.3, 0.0, 0.0) + t * 0.2)) * 0.25;
      float mu = max(dot(n, view), 0.0);
      surface = mix(surface * vec3(0.95, 0.45, 0.2), surface, pow(mu, 0.5)) * (0.4 + 0.6 * pow(mu, 0.4));
      emissive = 1.0;
    }

    vec3 col;
    if (emissive > 0.5) {
      col = surface * 1.45;
    } else {
      float diff = dot(n, L);
      float dN = dot(normalize(vWorldNormal), L);
      float day = smoothstep(-0.05, 0.22, dN);
      col = surface * (vec3(0.07, 0.075, 0.095) + 1.12 * max(diff, 0.0));
      if (gloss > 0.0) {
        vec3 H = normalize(L + view);
        float nh = max(dot(n, H), 0.0);
        col += vec3(1.0, 0.96, 0.9) * (pow(nh, 320.0) * 0.7 + pow(nh, 18.0) * 0.12) * gloss * day;
        float fr = pow(1.0 - max(dot(n, view), 0.0), 4.0);
        col = mix(col, vec3(0.2, 0.36, 0.72) * (0.2 + max(diff, 0.0)), fr * 0.4 * gloss);
      }
      float night = smoothstep(0.08, -0.2, dN);
      col += vec3(1.0, 0.72, 0.38) * nightLights * night * 1.6;
      col += mix(vec3(0.1, 1.0, 0.5), vec3(0.6, 0.2, 0.9), fbm3(p * 3.0)) * aurora * night * 0.6;
      float term = exp(-pow(dN / 0.16, 2.0));
      float rim = pow(1.0 - max(dot(n, view), 0.0), 3.0);
      vec3 atmo = uType == 1 ? mix(vec3(0.18, 0.38, 1.0), vec3(1.0, 0.5, 0.25), term) : uAtmo;
      col += atmo * rim * uAtmoPower * (0.15 + 0.85 * smoothstep(-0.35, 0.45, dN)) * (uType == 1 ? 1.2 : 1.0);
      if (uType == 1) col += vec3(1.0, 0.42, 0.18) * term * 0.08;
    }
    col += vec3(0.72, 0.65, 1.0) * uHighlight * pow(1.0 - max(dot(n, view), 0.0), 2.0);
    gl_FragColor = vec4(col, 1.0);
  }
`;

interface Style {
  type: number;
  a: string;
  b: string;
  c?: string;
  bands?: number;
  atmo?: string;
  atmoPower?: number;
  /** Stylised display radius (not to scale). */
  radius: number;
  /** Axial tilt in degrees, for visual interest. */
  tilt: number;
}

export const STYLE: Record<BodyId, Style> = {
  sun: { type: 6, a: "#ff7a14", b: "#ffe9a0", radius: 2.3, tilt: 0 },
  mercury: { type: 0, a: "#7b746e", b: "#4a4540", radius: 0.38, tilt: 0 },
  venus: { type: 2, a: "#b88a45", b: "#f0dca8", atmo: "#ffd9a0", atmoPower: 0.6, radius: 0.62, tilt: 177 },
  earth: { type: 1, a: "#000", b: "#000", atmo: "#4f85ff", atmoPower: 0.85, radius: 0.68, tilt: 23.4 },
  moon: { type: 0, a: "#34343a", b: "#bcb8c0", radius: 0.2, tilt: 0 },
  mars: { type: 3, a: "#8a4326", b: "#cf7a45", c: "#3a2018", atmo: "#e8956a", atmoPower: 0.3, radius: 0.46, tilt: 25 },
  ceres: { type: 0, a: "#4b4848", b: "#8f8a85", radius: 0.2, tilt: 4 },
  jupiter: { type: 4, a: "#c8a27a", b: "#efe0c8", c: "#8d5b3f", bands: 26, atmo: "#e8cfa5", atmoPower: 0.2, radius: 1.75, tilt: 3 },
  saturn: { type: 4, a: "#d9bf8c", b: "#f3e6c0", c: "#a8895a", bands: 14, atmo: "#f1dfae", atmoPower: 0.2, radius: 1.45, tilt: 27 },
  uranus: { type: 5, a: "#7fc8d4", b: "#b5e6ec", c: "#5fa7b8", bands: 6, atmo: "#9fe2ee", atmoPower: 0.55, radius: 1.0, tilt: 82 },
  neptune: { type: 5, a: "#2c4fc4", b: "#4f7bf0", c: "#1d3499", bands: 9, atmo: "#6f9bff", atmoPower: 0.6, radius: 0.98, tilt: 28 },
};

export function createBodyMaterial(id: BodyId, radius = STYLE[id].radius): THREE.ShaderMaterial {
  const s = STYLE[id];
  return new THREE.ShaderMaterial({
    vertexShader: VERT,
    fragmentShader: FRAG,
    uniforms: {
      uType: { value: s.type },
      uTime: { value: 0 },
      uRadius: { value: radius },
      uSun: { value: new THREE.Vector3(1, 0.3, 0.6).normalize() },
      uColA: { value: new THREE.Color(s.a) },
      uColB: { value: new THREE.Color(s.b) },
      uColC: { value: new THREE.Color(s.c ?? s.b) },
      uBands: { value: s.bands ?? 10 },
      uAtmo: { value: new THREE.Color(s.atmo ?? "#000000") },
      uAtmoPower: { value: s.atmoPower ?? 0 },
      uHighlight: { value: 0 },
    },
  });
}

export function createBodyMesh(id: BodyId, radius = STYLE[id].radius, segments = 64): THREE.Mesh {
  return new THREE.Mesh(new THREE.SphereGeometry(radius, segments, segments), createBodyMaterial(id, radius));
}

/* ---------------- Saturn's rings ---------------- */

const RING_VERT = /* glsl */ `
  varying vec3 vObj;
  varying vec3 vWorld;
  void main() {
    vObj = position;
    vec4 w = modelMatrix * vec4(position, 1.0);
    vWorld = w.xyz;
    gl_Position = projectionMatrix * viewMatrix * w;
  }
`;

const RING_FRAG = /* glsl */ `
  precision highp float;
  varying vec3 vObj;
  varying vec3 vWorld;
  uniform vec3 uCenter;
  uniform vec3 uSunPos;
  uniform float uR;
  uniform vec3 uNormal;
  float h1(float x) { return fract(sin(x * 91.3458) * 47453.5453); }
  void main() {
    float r = length(vObj.xy);
    // C ring (faint), B ring (dense), Cassini division, A ring with the Encke gap.
    float dens = 0.0;
    dens += smoothstep(1.25, 1.32, r) * (1.0 - smoothstep(1.48, 1.52, r)) * 0.28;
    dens += smoothstep(1.48, 1.55, r) * (1.0 - smoothstep(1.90, 1.94, r)) * 0.95;
    dens += smoothstep(2.00, 2.04, r) * (1.0 - smoothstep(2.30, 2.34, r)) * 0.72;
    dens *= 1.0 - smoothstep(0.004, 0.0, abs(r - 2.19) - 0.012) * 0.9;
    float ringlets = 0.80 + 0.20 * sin(r * 140.0 + sin(r * 31.0) * 3.0);
    float fine = 0.86 + 0.14 * h1(floor(r * 420.0));
    dens *= ringlets * fine;
    vec3 tan = mix(vec3(0.78, 0.68, 0.52), vec3(0.95, 0.88, 0.74), h1(floor(r * 60.0)));
    vec3 L = normalize(uSunPos - vWorld);
    vec3 N = normalize(uNormal);
    vec3 V = normalize(cameraPosition - vWorld);
    float lit = 0.32 + 0.68 * abs(dot(N, L));
    // Backlit rings glow because ice scatters light forward.
    float forward = pow(max(dot(-V, L), 0.0), 6.0) * 0.5 * (1.0 - dens * 0.5);
    // The planet's shadow: a ray toward the Sun that passes through the globe is blocked.
    vec3 dir = L;
    float t = dot(uCenter - vWorld, dir);
    float d = length(vWorld + dir * t - uCenter);
    float shadow = t > 0.0 ? smoothstep(uR * 0.97, uR * 1.04, d) : 1.0;
    vec3 col = tan * (lit * (0.16 + 0.84 * shadow) * 1.15 + forward * shadow);
    float alpha = dens * 0.95;
    if (alpha < 0.01) discard;
    gl_FragColor = vec4(col, alpha);
  }
`;

/** Saturn's rings, sized relative to the planet's radius. Call updateRings every frame so the planet's shadow falls correctly. */
export function createRings(planetRadius: number): THREE.Mesh {
  const geo = new THREE.RingGeometry(planetRadius * 1.25, planetRadius * 2.35, 192, 1);
  // Normalise so the shader can work in planet-radius units.
  const pos = geo.attributes.position;
  for (let i = 0; i < pos.count; i++) pos.setXYZ(i, pos.getX(i) / planetRadius, pos.getY(i) / planetRadius, 0);
  const mesh = new THREE.Mesh(
    geo,
    new THREE.ShaderMaterial({
      vertexShader: RING_VERT,
      fragmentShader: RING_FRAG,
      uniforms: { uCenter: { value: new THREE.Vector3() }, uSunPos: { value: new THREE.Vector3() }, uR: { value: planetRadius }, uNormal: { value: new THREE.Vector3(0, 1, 0) } },
      transparent: true,
      side: THREE.DoubleSide,
      depthWrite: false,
    }),
  );
  mesh.scale.setScalar(planetRadius);
  mesh.rotation.x = Math.PI / 2;
  mesh.userData.isRings = true;
  return mesh;
}

const _c = new THREE.Vector3();
const _n = new THREE.Vector3();
/** Keeps the rings' shading in step with the planet's position and the Sun. sunPos is the Sun's world position. */
export function updateRings(rings: THREE.Mesh, sunPos: THREE.Vector3): void {
  const u = (rings.material as THREE.ShaderMaterial).uniforms;
  rings.updateWorldMatrix(true, false);
  rings.getWorldPosition(_c);
  u.uCenter.value.copy(_c);
  u.uSunPos.value.copy(sunPos);
  // Ring geometry is normalised to planet radius = 1, so the world scale is the planet's world radius.
  u.uR.value = rings.matrixWorld.getMaxScaleOnAxis();
  // The ring's plane normal in world space.
  _n.set(0, 0, 1).transformDirection(rings.matrixWorld);
  u.uNormal.value.copy(_n);
}

/* ---------------- glow shells, corona, sky ---------------- */

const GLOW_VERT = /* glsl */ `
  varying vec3 vNormal;
  void main() {
    vNormal = normalize(normalMatrix * normal);
    gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
  }
`;
const GLOW_FRAG = /* glsl */ `
  varying vec3 vNormal;
  uniform vec3 uColor;
  uniform float uStrength;
  void main() {
    float i = pow(max(0.0, 0.75 - dot(vNormal, vec3(0.0, 0.0, 1.0))), 3.0);
    gl_FragColor = vec4(uColor, 1.0) * i * uStrength;
  }
`;

export function createGlow(radius: number, color: string, strength = 1.2): THREE.Mesh {
  return new THREE.Mesh(
    new THREE.SphereGeometry(radius, 48, 48),
    new THREE.ShaderMaterial({
      vertexShader: GLOW_VERT,
      fragmentShader: GLOW_FRAG,
      uniforms: { uColor: { value: new THREE.Color(color) }, uStrength: { value: strength } },
      blending: THREE.AdditiveBlending,
      side: THREE.BackSide,
      transparent: true,
      depthWrite: false,
    }),
  );
}

/** A canvas texture of streaming coronal rays around a bright core. */
export function coronaTexture(rays: number, seed = 1): THREE.CanvasTexture {
  const size = 512;
  const c = document.createElement("canvas");
  c.width = c.height = size;
  const g = c.getContext("2d")!;
  const cx = size / 2;
  let s = seed * 9301;
  const rnd = () => ((s = (s * 9301 + 49297) % 233280) / 233280);
  g.globalCompositeOperation = "lighter";
  for (let i = 0; i < rays; i++) {
    const a = rnd() * Math.PI * 2;
    const len = cx * (0.55 + rnd() * 0.45);
    const w = 0.012 + rnd() * 0.03;
    const grad = g.createRadialGradient(cx, cx, cx * 0.18, cx, cx, len);
    grad.addColorStop(0, "rgba(255,200,120,0.5)");
    grad.addColorStop(0.5, "rgba(255,140,60,0.15)");
    grad.addColorStop(1, "rgba(255,120,40,0)");
    g.fillStyle = grad;
    g.beginPath();
    g.moveTo(cx, cx);
    g.arc(cx, cx, len, a - w, a + w);
    g.closePath();
    g.fill();
  }
  const glow = g.createRadialGradient(cx, cx, 0, cx, cx, cx);
  glow.addColorStop(0, "rgba(255,230,170,0.95)");
  glow.addColorStop(0.25, "rgba(255,160,70,0.45)");
  glow.addColorStop(1, "rgba(255,110,30,0)");
  g.fillStyle = glow;
  g.fillRect(0, 0, size, size);
  return new THREE.CanvasTexture(c);
}

const SKY_VERT = /* glsl */ `
  varying vec3 vDir;
  void main() {
    vDir = normalize(position);
    gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
  }
`;

const SKY_FRAG = /* glsl */ `
  precision highp float;
  varying vec3 vDir;
  ${NOISE}
  void main() {
    vec3 d = normalize(vDir);
    // A tilted galactic band with dust lanes, plus faint coloured nebulae.
    float band = exp(-pow(dot(d, normalize(vec3(0.25, 0.9, 0.35))) * 3.2, 2.0));
    float dust = fbm3(d * 5.0 + 2.0);
    float lane = smoothstep(0.52, 0.72, fbm3(d * 9.0 + 7.0));
    vec3 col = vec3(0.55, 0.50, 0.85) * band * (0.35 + 0.65 * dust) * (1.0 - lane * 0.7) * 0.5;
    col += vec3(0.7, 0.3, 0.6) * pow(smoothstep(0.55, 0.9, fbm3(d * 2.2 + 11.0)), 2.0) * 0.16;
    col += vec3(0.2, 0.45, 0.8) * pow(smoothstep(0.58, 0.95, fbm3(d * 2.6 + 23.0)), 2.0) * 0.12;
    float a = clamp(max(col.r, max(col.g, col.b)) * 1.4, 0.0, 0.8);
    gl_FragColor = vec4(col, a);
  }
`;

export function createSkyDome(radius = 880): THREE.Mesh {
  const m = new THREE.Mesh(
    new THREE.SphereGeometry(radius, 48, 32),
    new THREE.ShaderMaterial({ vertexShader: SKY_VERT, fragmentShader: SKY_FRAG, side: THREE.BackSide, transparent: true, depthWrite: false, blending: THREE.AdditiveBlending }),
  );
  m.renderOrder = -10;
  return m;
}

/** A target reticle drawn on a canvas: dashed ring, tick marks and corner brackets. */
export function reticleTexture(color = "#b8a6e8"): THREE.CanvasTexture {
  const size = 256;
  const c = document.createElement("canvas");
  c.width = c.height = size;
  const g = c.getContext("2d")!;
  g.strokeStyle = color;
  g.lineWidth = 2;
  g.setLineDash([10, 8]);
  g.beginPath();
  g.arc(128, 128, 100, 0, Math.PI * 2);
  g.stroke();
  g.setLineDash([]);
  g.lineWidth = 3;
  for (let i = 0; i < 4; i++) {
    g.save();
    g.translate(128, 128);
    g.rotate((i * Math.PI) / 2);
    g.beginPath();
    g.moveTo(0, -122);
    g.lineTo(0, -106);
    g.stroke();
    g.beginPath();
    g.moveTo(-14, -122);
    g.lineTo(14, -122);
    g.stroke();
    g.restore();
  }
  g.lineWidth = 1;
  g.globalAlpha = 0.6;
  g.beginPath();
  g.arc(128, 128, 82, 0, Math.PI * 2);
  g.stroke();
  return new THREE.CanvasTexture(c);
}
